  addPair("          <input type=\"file\" ref={fileInputRef} onChange={handleFileChange} className=\"hidden\" accept=\"image/*,audio/*,.pdf\" />", "          <input type=\"file\" ref={fileInputRef} onChange={handleFileChange} className=\"hidden\" accept=\"image/*,audio/*,.pdf\" />");
  addPair("          <div className=\"flex items-center gap-3 overflow-x-auto pb-2 scrollbar-none\">", "          <div className=\"flex items-center gap-3 overflow-x-auto pb-2 scrollbar-none\">");
  addPair("            <button type=\"button\" onClick={() => fileInputRef.current?.click()} className=\"h-24 w-24 rounded-2xl border-2 border-dashed border-slate-700 hover:border-indigo-400 text-slate-400 hover:text-indigo-400 flex flex-col items-center justify-center gap-1 shrink-0 transition-colors cursor-pointer\">", "            <button type=\"button\" onClick={() => fileInputRef.current?.click()} className=\"h-24 w-24 rounded-2xl border-2 border-dashed border-slate-300 hover:border-indigo-600 text-slate-500 hover:text-indigo-600 flex flex-col items-center justify-center gap-1 shrink-0 transition-colors cursor-pointer\">");
  addPair("              <Plus className=\"w-5 h-5\" />", "              <Plus className=\"w-5 h-5\" />");
  addPair("              <span className=\"text-[10px] font-medium\">Add Item</span>", "              <span className=\"text-[10px] font-medium\">Add Item</span>");
