  addPair("                  {att.type === 'image' ? (", "                  {att.type === 'image' ? (");
  addPair("                    <div className=\"w-7 h-7 rounded-lg overflow-hidden bg-slate-700 flex items-center justify-center\">", "                    <div className=\"w-7 h-7 rounded-lg overflow-hidden bg-slate-200 flex items-center justify-center\">");
