  addPair("                    </div>", "                    </div>");
  addPair("                  )}", "                  )}");
  addPair("                  <button type=\"button\" onClick={() => deleteAttachmentStore(currentNote.id, att.id)} aria-label={`Delete ${att.name}`} className=\"opacity-0 group-hover:opacity-100 text-slate-400 hover:text-rose-400 transition-opacity p-0.5 cursor-pointer\">", "                  <button type=\"button\" onClick={() => deleteAttachmentStore(currentNote.id, att.id)} aria-label={`Delete ${att.name}`} className=\"opacity-0 group-hover:opacity-100 text-slate-400 hover:text-rose-600 transition-opacity p-0.5 cursor-pointer\">");
  addPair("                    <X className=\"w-3 h-3\" />", "                    <X className=\"w-3 h-3\" />");
  addPair("                  </button>", "                  </button>");
  addPair("                </div>", "                </div>");
  addPair("                <div className=\"min-w-0\">", "                <div className=\"min-w-0\">");
  addPair("                  <p className=\"text-xs font-medium text-slate-200 truncate\">{att.name}</p>", "                  <p className=\"text-xs font-medium text-slate-800 truncate\">{att.name}</p>");
  addPair("                  <p className=\"text-[10px] text-slate-400\">{att.size}</p>", "                  <p className=\"text-[10px] text-slate-500\">{att.size}</p>");
  addPair("                </div>", "                </div>");
  addPair("              </div>", "              </div>");
  addPair("            ))}", "            ))}");
  addPair("          </div>", "          </div>");
  addPair("        </div>", "        </div>");
  addPair("", "");

  // Action Buttons cleanly enclosed INSIDE the sheet container with pb-8 at the bottom of the card
  addPair("        {/* ACTION BUTTONS CLEANLY ENCLOSED INSIDE CONTENT CONTAINER */}", "        {/* ACTION BUTTONS CLEANLY ENCLOSED INSIDE CONTENT CONTAINER */}");
  addPair("        <div className=\"pt-2 space-y-3\">", "        <div className=\"pt-2 space-y-3\">");
  addPair("          <button type=\"button\" onClick={handleSaveNote} className=\"w-full h-12 rounded-2xl bg-indigo-600 hover:bg-indigo-500 text-white font-semibold text-sm flex items-center justify-center gap-2 shadow-md shadow-indigo-600/25 active:scale-[0.99] transition-all cursor-pointer\">", "          <button type=\"button\" onClick={handleSaveNote} className=\"w-full h-12 rounded-2xl bg-indigo-600 hover:bg-indigo-500 text-white font-semibold text-sm flex items-center justify-center gap-2 shadow-md shadow-indigo-600/25 active:scale-[0.99] transition-all cursor-pointer\">");
  addPair("            <Check className=\"w-4 h-4 stroke-[2.5]\" />", "            <Check className=\"w-4 h-4 stroke-[2.5]\" />");
