  addPair("      {/* DELETE CONFIRMATION MODAL */}", "      {/* DELETE CONFIRMATION MODAL */}");
  addPair("      {isDeleteModalOpen && (", "      {isDeleteModalOpen && (");
  addPair("        <div className=\"fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4\">", "        <div className=\"fixed inset-0 z-50 bg-black/40 backdrop-blur-sm flex items-center justify-center p-4\">");
  addPair("          <div className=\"w-full max-w-xs rounded-2xl p-5 space-y-4 bg-slate-800 border border-slate-700 shadow-2xl text-white\">", "          <div className=\"w-full max-w-xs rounded-2xl p-5 space-y-4 bg-white border border-slate-200 shadow-2xl text-slate-900\">");
  addPair("            <div className=\"w-10 h-10 rounded-full bg-rose-500/15 text-rose-400 flex items-center justify-center mx-auto\">", "            <div className=\"w-10 h-10 rounded-full bg-rose-50 text-rose-600 flex items-center justify-center mx-auto\">");
  addPair("              <AlertTriangle className=\"w-5 h-5\" />", "              <AlertTriangle className=\"w-5 h-5\" />");
  addPair("            </div>", "            </div>");
  addPair("            <div className=\"text-center space-y-1\">", "            <div className=\"text-center space-y-1\">");
  addPair("              <h3 className=\"font-bold text-sm text-white\">Delete Note?</h3>", "              <h3 className=\"font-bold text-sm text-slate-900\">Delete Note?</h3>");
  addPair("              <p className=\"text-xs text-slate-400\">This note will be permanently removed from your storage.</p>", "              <p className=\"text-xs text-slate-500\">This note will be permanently removed from your storage.</p>");
  addPair("            </div>", "            </div>");
  addPair("            <div className=\"flex items-center gap-2 pt-1\">", "            <div className=\"flex items-center gap-2 pt-1\">");
  addPair("              <button type=\"button\" onClick={() => setIsDeleteModalOpen(false)} className=\"flex-1 py-2.5 rounded-xl text-xs font-semibold bg-slate-700 text-slate-200 hover:bg-slate-600 cursor-pointer\">Cancel</button>", "              <button type=\"button\" onClick={() => setIsDeleteModalOpen(false)} className=\"flex-1 py-2.5 rounded-xl text-xs font-semibold bg-slate-100 text-slate-700 hover:bg-slate-200 cursor-pointer\">Cancel</button>");
  addPair("              <button type=\"button\" onClick={handleDeleteConfirm} className=\"flex-1 py-2.5 rounded-xl text-xs font-semibold bg-rose-600 text-white shadow-sm hover:bg-rose-500 cursor-pointer\">Delete</button>", "              <button type=\"button\" onClick={handleDeleteConfirm} className=\"flex-1 py-2.5 rounded-xl text-xs font-semibold bg-rose-600 text-white shadow-sm hover:bg-rose-500 cursor-pointer\">Delete</button>");
  addPair("            </div>", "            </div>");
  addPair("          </div>", "          </div>");
  addPair("        </div>", "        </div>");
  addPair("      )}", "      )}");
  addPair("", "");

  // Toast
  addPair("      {/* TOAST FEEDBACK */}", "      {/* TOAST FEEDBACK */}");
  addPair("      {toastMessage && (", "      {toastMessage && (");
  addPair("        <div className=\"fixed top-16 left-1/2 -translate-x-1/2 z-50 px-4 py-2 rounded-full bg-slate-800 border border-slate-700 text-white text-xs font-medium shadow-xl flex items-center gap-2 animate-in fade-in duration-150\">", "        <div className=\"fixed top-16 left-1/2 -translate-x-1/2 z-50 px-4 py-2 rounded-full bg-slate-900 text-white text-xs font-medium shadow-xl flex items-center gap-2 animate-in fade-in duration-150\">");
  addPair("          <Check className=\"w-3.5 h-3.5 text-emerald-400\" />", "          <Check className=\"w-3.5 h-3.5 text-emerald-400\" />");
